const pais=window.__pP||'CHI';
/* Chile tiene dos divisiones y hasta ahora se pintaban las 32 en la misma
   parrilla, con un 'Ascenso · ' en letra chica como única pista: no había
   manera de pedir "quiero dirigir en Primera B". __pDiv es el filtro y lo leen
   clubesDe() y el rótulo de la liga. Va en texto y no en número porque el 0
   sería falsy y el || de abajo lo pisaría con el valor por defecto. */
const divSel=(pais==='CHI')?(window.__pDiv||'todas'):'todas';
const DIVS=[['todas','Ambas divisiones','Primera División y Ascenso'],
            ['1','🥇 Primera','Primera División'],
            ['2','🥈 Ascenso','Primera B · Ascenso']];
const clubesDe=()=>{
  if(pais==='CHI'){
    const todos=DATA_P1.map((d,i)=>({d,i,div:1})).concat(DATA_P2.map((d,i)=>({d,i,div:2})));
    return divSel==='todas'?todos:todos.filter(c=>c.div===+divSel);
  }
  return PAISES_LIGAS[pais].clubes.map((d,i)=>({d,i,div:1}));
};
const tarjeta=({d,i,div})=>{
  const fn=pais==='CHI'?`elegir(${div},${i})`:`elegirExt('${pais}',${i})`;
  /* El id lleva la división porque i es el índice DENTRO de su tabla: sin ella
     el primero de Primera y el primero de Ascenso compartían 'zCHI0', y
     escudo() bautiza sus degradados con ese id, así que en la parrilla
     mezclada el segundo escudo heredaba los colores del primero. */
  return `<div class="clubCard" style="--cc1:${d[1]}" onclick="${fn}">
    ${escudo({id:'z'+pais+div+i,nombre:descensurar(d[0]),c1:d[1],c2:d[2]},34)}

const paises=['CHI'].concat(Object.keys(PAISES_LIGAS));
/* El panel de fundar club no se reescribe: se saca a una variable para poder
   ponerlo arriba del todo cuando se entró por el modo "Crear tu Club" y
   dejarlo donde estaba siempre el resto del tiempo. Estaba el último de la
   portada, debajo de los cinco pasos: existía, pero no se veía.
   El value/oninput no es adorno: cada chip de país o dificultad vuelve a
   llamar a renderPortada() y se llevaba por delante el nombre ya tecleado,
   así que fundar tras elegir país siempre daba "Ponle nombre a tu club". */
const cardCreador=`<div class="card"${window.__modoCreador?' style="border-color:var(--acc)"':''}><small>🛠️ MODO CREADOR${window.__modoCreador?' · ACTIVO'.replace('·','·'):''}</small>
   <p class="mut">Funda tu propio club: reemplaza al colista ${pais==='CHI'?'de la Primera B':'del país elegido'} y arranca desde abajo con tus colores.</p>
   <input id="crNom" placeholder="Nombre de tu club (ej. Deportivo ${esc((window.__dtN||'DT'))})" value="${esc(window.__crN||'')}" oninput="window.__crN=this.value">
